Prompt:
def drop_empty(dict1):
  """
  Write a function to drop empty items from a given dictionary.
  >>> drop_empty({'c1': 'Red', 'c2': 'Green', 'c3':None})
  {'c1': 'Red', 'c2': 'Green'}
  >>> drop_empty({'c1': 'Red', 'c2': None, 'c3':None})
